const axios = require("axios");

async function getUrlInfo(url) {
  try {
    const response = await axios.get(
      "https://audioconverter.ai/api/v1/transcriptions/url-info",
      {
        params: {
          url: url,
          type: 3,
          action: "download"
        },
        headers: {
          "Accept": "application/json, text/plain, */*",
        }
      }
    );
    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

async function getDownloadStatus(taskId) {
  try {
    const response = await axios.get(
      "https://audioconverter.ai/api/v1/transcriptions/download-status",
      {
        params: {
          task_id: taskId
        },
        headers: {
          "Accept": "application/json, text/plain, */*",
        }
      }
    );
    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

async function processVideo(videoUrl) {
  const urlInfo = await getUrlInfo(videoUrl);

  if (urlInfo.error) {
    return m.reply(`Error getting URL info: ${urlInfo.error}`);
  }

  if (urlInfo.code === 100000 && urlInfo.data && urlInfo.data.videos && urlInfo.data.videos.length > 0) {
    const videoId = urlInfo.data.videos[0].video_id;
    const downloadStatus = await getDownloadStatus(videoId);

    if (downloadStatus.error) {
      return m.reply(`Error getting download status: ${downloadStatus.error}`);
    }

    if (downloadStatus.code === 100000 && downloadStatus.data && downloadStatus.data.url) {
      return m.reply(JSON.stringify(downloadStatus.data, null, 2));
    } else {
      return m.reply(`Download failed: ${downloadStatus.message}`);
    }
  } else {
    return m.reply(`Failed to retrieve video information or no videos found: ${urlInfo.message}`);
  }
}

const youtubeUrl = "https://youtu.be/ObuP-wH0ghA?si=pwdwhVr8cZLBgXAh";
processVideo(youtubeUrl);
